const el=(tag,cls,text)=>{const x=document.createElement(tag);x.className=cls||'';if(text!==undefined)x.textContent=text;return x};
export function renderCreditShop(root,m,checkout){
 const w=m.creditWallet||{included:0,permanent:m.credits||0,weeklyLimit:0},section=el('section','ws-card credit-wallet-summary');section.append(el('h2','','Кредиты'),el('p','',`Всего: ${m.credits||0} · Подписка: ${w.included} · Покупные и выданные: ${w.permanent}`),el('p','',w.nextRefillAt?'Следующее обновление: '+new Date(w.nextRefillAt).toLocaleString('ru-RU')+' (до '+w.weeklyLimit+' кр.)':'Недельное пополнение доступно на действующей подписке.'),el('p','account-note','Раз в 7 дней остаток кредитов подписки обновляется до лимита тарифа. Недельные остатки не копятся. Покупные и выданные администратором кредиты не сгорают. Сначала расходуются кредиты подписки.'));root.append(section);
 const shop=el('section','credit-shop');shop.id='credits';shop.append(el('h2','','Купить дополнительные кредиты'),el('p','','Не сгорают и не меняют подписку. Для создания видео по-прежнему нужен Lite, Plus или Pro.'));const grid=el('div','credit-pack-grid');for(const pack of m.creditPacks||[]){const card=el('article','ws-card credit-pack-card'),b=el('button','ws-primary','Купить '+pack.credits+' кр.');b.type='button';b.onclick=()=>checkout({pack_id:pack.id});card.append(el('h3','',pack.name),el('strong','',(pack.price_minor/100).toLocaleString('ru-RU')+' ₽'),b);grid.append(card)}shop.append(grid);if(!m.authenticated){const a=el('a','ws-primary','Войти и посмотреть пакеты');a.href='login.html?next=%2Fpricing.html';shop.append(a)}else if(!m.paymentReady)shop.append(el('p','payment-pending','Онлайн-оплата станет доступна после подключения платёжного сервиса владельцем. Счета пока не создаются.'));root.append(shop);
}
